// Generated by tools/gen_dsp_assets.py — the enrollment DSP tables,
// base64-encoded float32 (little-endian), one per filterbank. Do not edit by hand.
export const DSP_B64: Record<string, string> = {
  s3_mel_filters: "",
  s3_hann400: "",
  matcha_mel_filters: "",
  matcha_hann1920: "",
  voiceenc_mel_filters: "",
  voiceenc_hann400: "",
  kaldi_mel_filters: "",
  kaldi_povey400: "",
};

export function decodeF32(b64: string): Float32Array {
  const bytes = Buffer.from(b64, "base64");
  const out = new Float32Array(bytes.length / 4);
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  for (let i = 0; i < out.length; i++) out[i] = dv.getFloat32(i * 4, true);
  return out;
}
